/* ===== HARD questions: E2 — electromagnetism, motors, generators, transformers, AC, deep history, units, safety ===== */
const _E2_N0 = DATA.questions.length;
const _D = { dg: 1 };
const _F = id => ({ dg: 1, fig: id });

/* ---------- Lorentz force / velocity selector / magnets (c11) ---------- */
NUM('c11', 4, "A proton (m = 1.673×10⁻²⁷ kg, q = 1.602×10⁻¹⁹ C) moves at 2.0×10⁶ m/s perpendicular to a uniform 0.50 T field. What is the radius of its circular path, in cm?", 4.18, 'cm', "The magnetic force supplies the centripetal force: qvB = mv²/r, so r = mv/(qB) = (1.673×10⁻²⁷)(2.0×10⁶)/((1.602×10⁻¹⁹)(0.50)) = 0.0418 m = 4.18 cm.", _D);
NUM('c11', 4, "A proton (m = 1.673×10⁻²⁷ kg) circulates in a uniform 1.5 T field. How many MHz is its cyclotron frequency f = qB/(2πm)?", 22.9, 'MHz', "f = qB/(2πm) = (1.602×10⁻¹⁹)(1.5)/(2π × 1.673×10⁻²⁷) = 2.286×10⁷ Hz = 22.9 MHz. The frequency does not depend on speed or radius.", _D);
NUM('c11', 5, "An electron and a proton are each accelerated from rest through the same potential difference and then enter the same uniform magnetic field perpendicular to their velocity. What is the ratio r_proton / r_electron of their orbit radii? (m_p/m_e = 1836)", 42.9, '', "qV = ½mv² gives v = √(2qV/m). r = mv/(qB) = √(2mV/q)/B, so r ∝ √m for equal charge magnitude. Ratio = √1836 = 42.9.", { dg: 1, tol: 0.03 });
NUM('c11', 4, "The figure shows a velocity selector. What speed, in 10⁶ m/s, does a charged particle need in order to pass straight through undeflected?", 1.5, '×10⁶ m/s', "E = V/d = 600 V / 0.020 m = 3.0×10⁴ V/m. Undeflected when qE = qvB, so v = E/B = 3.0×10⁴ / 0.020 = 1.5×10⁶ m/s.", _F('qf-c2-selector'));
MC('c11', 5, "A velocity selector (crossed uniform E and B fields) lets a singly charged ion of speed v = E/B pass straight through. A second ion has twice the mass, twice the charge and the same speed v. What happens to it?", ['It is deflected in the direction of E, because it carries more charge', 'It passes straight through as well', 'It is deflected in the direction of the magnetic force, because it is heavier', 'It is stopped, because qE exceeds mv²'], 1, "The electric force qE and magnetic force qvB both scale with q, so they still cancel whenever v = E/B. Mass and charge drop out of the selector condition; only speed matters.", _D);
MC('c11', 4, "A long straight wire carries current out of the page. Looking at the page, the magnetic field lines near the wire are:", ['radial, pointing away from the wire', 'circles around the wire, counterclockwise', 'circles around the wire, clockwise', 'straight lines parallel to the wire'], 1, "Right-hand rule: thumb along the current (out of page), fingers curl counterclockwise as seen from the tip of the thumb. So B circulates counterclockwise.", _D);
NUM('c11', 4, "A straight 0.30 m wire carrying 4.0 A lies at 30° to a uniform 0.50 T field. What is the magnetic force on it, in N?", 0.30, 'N', "F = BIL sinθ = 0.50 × 4.0 × 0.30 × sin 30° = 0.30 N. (Using cos 30° instead would be the classic trap.)", _D);
NUM('c11', 5, "Two long parallel wires 4.0 cm apart carry 10 A and 20 A in the same direction. What is the force per unit length between them in mN/m? (μ₀ = 4π×10⁻⁷ T·m/A)", 1.0, 'mN/m', "F/L = μ₀I₁I₂/(2πd) = 2×10⁻⁷ × 10 × 20 / 0.040 = 1.0×10⁻³ N/m = 1.0 mN/m. Same-direction currents attract.", _D);
MC('c11', 4, "You cut a bar magnet exactly in half between its poles. What do you get?", ['One north-only piece and one south-only piece', 'Two complete magnets, each with its own north and south pole', 'Two unmagnetised pieces of iron', 'Two magnets with half the pole strength but only one pole each'], 1, "Magnetic monopoles have never been found; every piece is a dipole. Each half is a weaker but complete magnet.", _D);
TF('c11', 5, "A permanent magnet loses its ferromagnetism permanently if it is heated above its Curie temperature and cooled with no external field.", true, "Above the Curie temperature thermal agitation destroys the domain alignment; on cooling in zero field the domains settle randomly (unless re-magnetised). For iron T_C is about 770 °C.", _D);
MC('c11', 4, "Which statement about Earth’s magnetic field is correct?", ['The compass needle end that points north is a magnetic south pole, because Earth\'s geographic north is near a magnetic south pole of Earth\'s dipole', 'Earth\'s geographic north pole is near a magnetic north pole of the Earth\'s dipole, so a compass north end is attracted to a north pole', 'Field lines leave the Earth near the geographic south pole and enter near the geographic north pole, so the compass needle is a south-seeking magnet', 'The compass needle end that points north is a magnetic north pole, and it is attracted because Earth\'s geographic north is near a magnetic south pole'], 3, "Unlike poles attract. The north-seeking end of a compass is by definition a magnetic north pole, so it points toward a magnetic south pole of Earth’s dipole, which lies near geographic north. (Calling the needle end a south pole is the common mistake.)", _D);

/* ---------- solenoids / Helmholtz / inductors (c12, c24) ---------- */
NUM('c12', 4, "A solenoid has 800 turns wound uniformly on a 0.25 m long air core and carries 2.0 A. What is the field inside, in mT? (μ₀ = 4π×10⁻⁷)", 8.04, 'mT', "n = 800/0.25 = 3200 turns/m. B = μ₀nI = 4π×10⁻⁷ × 3200 × 2.0 = 8.04×10⁻³ T = 8.04 mT.", _D);
NUM('c12', 5, "A Helmholtz pair has two identical coils of radius R = 0.10 m, each with N = 100 turns, spaced one radius apart and each carrying 1.0 A in the same sense. Use B = (4/5)^(3/2) μ₀NI/R at the midpoint. What is B in mT?", 0.899, 'mT', "(4/5)^(3/2) = 0.7155. B = 0.7155 × 4π×10⁻⁷ × 100 × 1.0 / 0.10 = 8.99×10⁻⁴ T = 0.899 mT.", { dg: 1, tol: 0.03 });
NUM('c24', 4, "A 12 V source is switched onto a series circuit of a 10 Ω resistor and a 0.50 H inductor. What is the current, in A, 50 ms after closing the switch?", 0.759, 'A', "τ = L/R = 0.50/10 = 50 ms. I = (V/R)(1 − e^(−t/τ)) = 1.2 × (1 − e⁻¹) = 1.2 × 0.632 = 0.759 A.", _D);
MC('c24', 4, "Just after a switch connects an inductor that initially carries no current to a DC source, and again long after, the inductor behaves respectively like:", ['a short circuit, then an open circuit', 'an open circuit, then a short circuit', 'an open circuit both times', 'a short circuit both times'], 1, "An inductor opposes a sudden change in current (V = L dI/dt): at t = 0 the current is zero, like an open circuit. At DC steady state dI/dt = 0, so V = 0 and it is a short (apart from winding resistance).", _D);

/* ---------- Faraday / Lenz / motional EMF (c32, c13) ---------- */
NUM('c32', 4, "In the figure, a rod slides at constant speed on frictionless rails joined by a resistor; the rails and rod have negligible resistance. What horizontal force, in N, must be applied to keep the rod moving at constant speed?", 0.144, 'N', "EMF = BLv = 0.30 × 0.40 × 5.0 = 0.60 V. I = 0.60/0.50 = 1.2 A. Magnetic drag F = BIL = 0.30 × 1.2 × 0.40 = 0.144 N; the pushing force must equal it.", _F('qf-c2-rail'));
NUM('c32', 4, "In the figure, the rod is pulled at constant speed across the rails. What is the electrical power dissipated in the resistor, in W?", 0.72, 'W', "EMF = BLv = 0.30 × 0.40 × 5.0 = 0.60 V. P = V²/R = 0.36/0.50 = 0.72 W. Check: the pulling force (0.144 N) times speed (5.0 m/s) also gives 0.72 W, so energy is conserved.", _F('qf-c2-rail'));
MC('c32', 5, "A rod slides right on rails in a field that points into the page (see figure). Which way does the induced current flow through the rod, and why?", ['Up the page, because the force on positive charge v × B points up', 'Down the page, because the force on positive charge v × B points down', 'Up the page, because the induced current must create a field into the page', 'No current flows unless the rod accelerates'], 0, "v × B for v to the right and B into the page: x̂ × (−ẑ) = +ŷ, so charges are pushed up the page, and current flows up through the rod. Check with Lenz: flux into the page is increasing (the loop area grows); the induced current must make a field out of the page inside the loop, which is counterclockwise as seen from the front, and that is up through the rod (the moving side) when the loop is to its left.", _F('qf-c2-rail'));
MC('c32', 4, "In the figure a bar magnet moves toward a ring, N pole first. The observer looks at the ring from the magnet’s side. Which way does the induced current circulate as the observer sees it, and what does the ring do?", ['Counterclockwise; the ring is repelled by the magnet', 'Clockwise; the ring is repelled by the magnet', 'Counterclockwise; the ring is attracted to the magnet', 'Clockwise; the ring is attracted to the magnet'], 0, "The flux through the ring (pointing away from the N pole, toward the ring) increases. The ring makes an opposing field pointing back toward the observer, which is a counterclockwise current as seen by the observer. That makes the ring face a north pole toward the incoming N pole: repulsion, opposing the motion (Lenz).", _F('qf-c2-lenz'));
NUM('c32', 4, "A coil of 200 turns has cross-sectional area 5.0×10⁻³ m². It starts with its plane perpendicular to a uniform 0.40 T field (maximum flux) and is turned in 0.020 s until its plane is parallel to the field. What average EMF, in V, is induced?", 20, 'V', "Flux goes from BA = 0.40 × 5.0×10⁻³ = 2.0×10⁻³ Wb to zero. EMF = NΔΦ/Δt = 200 × 2.0×10⁻³ / 0.020 = 20 V.", _D);
NUM('c32', 4, "A 50-turn loop of area 0.020 m² sits in a uniform 0.50 T field with its normal at 60° to the field. It is rotated so its normal is along the field (0°) in 0.10 s. What average EMF magnitude, in V, is induced?", 2.5, 'V', "Φ₁ = BA cos 60° = 0.50 × 0.020 × 0.5 = 5.0×10⁻³ Wb; Φ₂ = BA = 1.0×10⁻² Wb. ΔΦ = 5.0×10⁻³ Wb. EMF = NΔΦ/Δt = 50 × 5.0×10⁻³ / 0.10 = 2.5 V.", _D);
NUM('c32', 4, "The graph shows the magnetic flux through a 25-turn coil against time. What is the magnitude of the EMF induced between t = 4 s and t = 5 s, in V?", 3.0, 'V', "Between 4 s and 5 s the flux goes from +0.08 Wb to −0.04 Wb, so |ΔΦ| = 0.12 Wb in 1 s. EMF = N|ΔΦ/Δt| = 25 × 0.12 = 3.0 V. (Flat sections give zero EMF even though the flux is large.)", _F('qf-c2-phi'));
MC('c13', 5, "A strong magnet is dropped down a vertical copper tube. It takes much longer to emerge than a non-magnetic object of the same mass. The best explanation is:", ['Copper is weakly attracted to the magnet and pulls it upward', 'Eddy currents induced in the tube create a field that opposes the magnet\'s motion, so some gravitational energy is dissipated as heat', 'Air inside the tube is compressed and cushions the fall', 'The magnet loses its magnetism inside the tube and becomes lighter'], 1, "The changing flux through the copper induces circulating eddy currents (Faraday). By Lenz’s law their field opposes the motion, giving a drag force; the lost gravitational energy heats the tube (I²R).", _D);
MC('c13', 4, "Transformer cores are built from stacked insulated laminations instead of one solid block of iron. The main reason is to:", ['increase the core\'s permanent magnetisation', 'reduce eddy-current losses', 'increase the turns ratio', 'make the transformer work on DC'], 1, "Laminations break up the paths available to circulating eddy currents, cutting I²R heating in the core. Silicon steel also lowers hysteresis loss.", _D);
MC('c13', 5, "An ideal-ish 120 V / 12 V transformer is connected to a 12 V car battery (DC) on its 12 V winding, and the 120 V winding is left open. After the switch has been closed for a long time, the output winding shows:", ['120 V DC', 'about 120 V AC', 'essentially 0 V', '1.2 V AC'], 2, "A transformer needs a changing flux. With steady DC the flux is constant after the brief start-up transient, so no EMF is induced in the other winding. The primary winding alone behaves as a low-resistance coil and may overheat.", _D);

/* ---------- transformers & transmission ---------- */
NUM('c13', 4, "A transformer has 600 primary turns on a 120 V supply and 50 secondary turns feeding a 6.0 Ω resistor. Assuming it is ideal, what primary current flows, in A?", 0.139, 'A', "V_s = 120 × 50/600 = 10 V. I_s = 10/6.0 = 1.667 A. Power = 16.7 W, so I_p = 16.7/120 = 0.139 A (or I_p = I_s × N_s/N_p).", _D);
NUM('c13', 5, "A 10:1 step-down ideal transformer (primary:secondary) has an 8.0 Ω load on the secondary and is fed from 120 V. What current, in A, does the 120 V source supply?", 0.15, 'A', "Load seen by the source is R × (N_p/N_s)² = 8 × 100 = 800 Ω. I_p = 120/800 = 0.15 A. (Check: V_s = 12 V, I_s = 1.5 A, I_p = 0.15 A.)", _D);
NUM('c13', 4, "A transformer is 95 % efficient. Its primary takes 2.0 A at 120 V and its secondary delivers 12 V. What secondary current, in A?", 19, 'A', "P_in = 240 W. P_out = 0.95 × 240 = 228 W. I_s = 228/12 = 19 A.", _D);
NUM('c13', 4, "In the figure, the plant generates 500 kW at 5.0 kV. A 1:10 ideal step-up transformer feeds a transmission line whose total resistance (both wires) is 4.0 Ω. What power, in W, is lost as heat in the line?", 400, 'W', "Line voltage = 50 kV, so I = 500 kW / 50 kV = 10 A. P_loss = I²R = 100 × 4.0 = 400 W. Without the transformer, I = 100 A and the loss would be 40 kW: a factor of 100 larger.", _F('qf-c2-line'));
NUM('c13', 5, "A load draws 50 kW at 2.0 kV (unity power factor) from the end of a line whose total resistance is 5.0 Ω. Ignoring transformer losses, what power, in kW, must the generating plant supply?", 53.1, 'kW', "I in the line at the load end of the line = 50 kW / 2.0 kV = 25 A (the load’s 2.0 kV is at the line’s end). P_loss = 25² × 5 = 3125 W. Plant output = 50 + 3.125 = 53.1 kW.", { dg: 1, tol: 0.01 });
MC('c13', 4, "Power companies transmit electric power at very high voltage mainly because, for the same power delivered:", ['higher voltage means lower current, so I²R loss in the line is much smaller', 'higher voltage makes the wire resistance smaller', 'higher voltage makes the frequency lower, reducing losses', 'high voltage is safer for the public'], 0, "P = VI, so raising V lowers I for a given P. Line loss = I²R falls as 1/V². Wire resistance and frequency do not change, and high voltage is actually more dangerous.", _D);
MC('c13', 5, "A long line delivers power with loss P_loss. If the line voltage is tripled at the same delivered power and the same line resistance, the loss becomes:", ['P_loss / 3', 'P_loss / 9', 'P_loss / 6', '3 P_loss'], 1, "I falls by a factor of 3, and loss ∝ I², so loss falls by 9.", _D);

/* ---------- AC: RMS, peak, three-phase, generators (c10, c32) ---------- */
NUM('c10', 4, "A sinusoidal voltage measures 340 V peak-to-peak on an oscilloscope. What is its RMS value, in V?", 120, 'V', "Peak = 340/2 = 170 V. V_rms = 170/√2 = 120.2 V. (Using the peak-to-peak value in the formula is the trap.)", _D);
NUM('c10', 5, "A voltage v(t) = 5 V + (10 V) sin ωt is applied to a resistor. What is its RMS value, in V?", 8.66, 'V', "V_rms² = V_dc² + V_ac,rms² = 25 + (10/√2)² = 25 + 50 = 75, so V_rms = √75 = 8.66 V. (DC and AC rms add in quadrature.)", _D);
NUM('c10', 5, "A square-wave source switches between 0 V and 10 V, spending 30 % of each period at 10 V. What is its RMS voltage, in V?", 5.48, 'V', "V_rms² = average of v² = 0.30 × 100 = 30, so V_rms = √30 = 5.48 V (its average is 3.0 V).", _D);
NUM('c10', 4, "A 1500 W resistive heater runs from 120 V RMS. What is the peak current, in A?", 17.7, 'A', "I_rms = P/V = 1500/120 = 12.5 A. I_peak = 12.5 × √2 = 17.7 A.", _D);
NUM('c10', 4, "A 60 Hz sine wave v = V_p sin(ωt) starts at zero volts. How long, in ms, until it first reaches half its peak value?", 1.39, 'ms', "sin(ωt) = 0.5 → ωt = 30° = 1/12 of a cycle. t = T/12 = (1/60)/12 = 1.39 ms.", _D);
NUM('c10', 4, "In a balanced three-phase wye (star) system each phase-to-neutral voltage is 120 V RMS. What is the line-to-line voltage, in V?", 208, 'V', "Two phases 120° apart: V_LL = 2 × 120 × sin 60° = √3 × 120 = 208 V. The common 120/208 V service is exactly this.", _D);
NUM('c10', 5, "Three identical 10 Ω resistors are connected in wye across a balanced three-phase supply with 208 V line-to-line. What is the total power dissipated, in kW?", 4.33, 'kW', "Each resistor sees 208/√3 = 120.1 V, so P each = 120.1²/10 = 1442 W. Total = 3 × 1442 = 4.33 kW. Shortcut: P = V_LL²/R = 208²/10 = 4326 W.", { dg: 1, tol: 0.03 });
MC('c10', 4, "In a balanced three-phase system with three equal resistive loads in wye, the three phase voltages are sinusoids of equal amplitude that are:", ['in phase with each other', '90° apart', '120° apart, and the neutral carries zero current', '180° apart, and the neutral carries the sum of the currents'], 2, "Phases are spaced 120° apart (one third of a cycle). For equal loads the three currents sum to zero at every instant, so the neutral carries no current.", _D);
NUM('c32', 5, "A rectangular generator coil has 100 turns, area 0.030 m² and spins at 50 Hz in a uniform 0.20 T field. What is the RMS EMF, in V? (peak EMF = NBAω)", 133, 'V', "ω = 2π × 50 = 314.2 rad/s. E_peak = 100 × 0.20 × 0.030 × 314.2 = 188.5 V. E_rms = 188.5/√2 = 133 V.", { dg: 1, tol: 0.03 });
MC('c32', 5, "A simple AC generator’s rotation rate is doubled with the field strength unchanged. What happens to the output?", ['Peak EMF doubles and frequency doubles', 'Peak EMF doubles, frequency unchanged', 'Peak EMF unchanged, frequency doubles', 'Peak EMF quadruples, frequency doubles'], 0, "EMF = NBAω sin ωt: the amplitude is proportional to ω and the frequency f = ω/2π is proportional to ω. Both double.", _D);
NUM('c30', 4, "A 4-pole synchronous generator is driven at 1800 rpm. What frequency, in Hz, does it produce? (f = P·N/120)", 60, 'Hz', "f = 4 × 1800 / 120 = 60 Hz.", _D);

/* ---------- motors: physics (c29) ---------- */
NUM('c29', 4, "A DC motor draws 10 A from a 48 V supply. Its armature resistance is 0.80 Ω, and friction and windage absorb a further 40 W of mechanical power. What is its efficiency, in %?", 75, '%', "P_in = 480 W. Copper loss = 10² × 0.80 = 80 W. Shaft output = 480 − 80 − 40 = 360 W. Efficiency = 360/480 = 75 %.", _D);
NUM('c29', 4, "A permanent-magnet motor on a 12 V supply (armature resistance 2.0 Ω) runs at 600 rpm drawing 1.0 A. It is loaded down to 400 rpm with the supply unchanged. What armature current, in A, flows at 400 rpm?", 2.67, 'A', "ε = 12 − 1.0 × 2.0 = 10 V at 600 rpm. Back-EMF ∝ speed, so at 400 rpm ε = 6.67 V. I = (12 − 6.67)/2.0 = 2.67 A. Torque (∝ I) rose to match the load.", _D);
NUM('c29', 5, "A brushed permanent-magnet motor has a torque constant k = 0.050 N·m/A (= 0.050 V·s/rad). Its armature resistance is 1.0 Ω and it runs on 12 V. What is its stall torque, in N·m?", 0.60, 'N·m', "Stall current = 12/1.0 = 12 A (no back-EMF). τ = kI = 0.050 × 12 = 0.60 N·m.", _D);
NUM('c29', 5, "A brushed permanent-magnet motor has k_e = 0.050 V·s/rad, armature resistance 1.0 Ω, no friction, and runs on 12 V with no load. What is its no-load speed, in rpm?", 2290, 'rpm', "With no load and no friction the current is zero, so ε = V = 12 V. ω = 12/0.050 = 240 rad/s = 240 × 60/(2π) = 2290 rpm.", { dg: 1, tol: 0.03 });
NUM('c29', 5, "A 12 V permanent-magnet motor has stall torque 0.12 N·m and no-load speed 3000 rpm (torque falls linearly with speed). What is its maximum mechanical output power, in W?", 9.42, 'W', "Torque-speed line: τ = τ_s(1 − ω/ω₀). P = τω is maximum at ω₀/2 where τ = τ_s/2, so P_max = τ_s ω₀/4. ω₀ = 3000 × 2π/60 = 314.2 rad/s. P_max = 0.12 × 314.2 / 4 = 9.42 W (at 1500 rpm).", { dg: 1, tol: 0.03 });
NUM('c29', 3, "A motor with 3.0 Ω winding resistance is jammed (stalled) on a 12 V battery that has 1.0 Ω of internal resistance. What power, in W, is dissipated in the motor winding?", 27, 'W', "I = 12/(3.0 + 1.0) = 3.0 A. P = I²R = 9 × 3.0 = 27 W in the motor (9 W more is lost in the battery).", _D);
MC('c29', 4, "A permanent-magnet DC motor spinning in the forward direction has its supply leads swapped. Compared with before, it will:", ['run in the opposite direction', 'run the same direction, because the field is permanent', 'stop and stay stopped', 'run at the same speed but produce no torque'], 0, "Torque direction follows the armature current for a fixed field. Reversing the supply reverses the current, so the motor reverses. (Brushed PM motors are reversed exactly this way.)", _D);
MC('c29', 5, "A DC motor is being driven by an external source (for example a vehicle going downhill) so that its speed rises above its no-load speed for the applied voltage. The armature current then:", ['stays zero', 'reverses, and the machine acts as a generator returning energy to the supply', 'doubles in the same direction', 'is limited to V/R_a'], 1, "Above the no-load speed the back-EMF exceeds the supply voltage, so (ε − V)/R_a reverses the current. Electrical power flows back to the source: this is regenerative braking.", _D);

/* ---------- motors: types, control (c30) ---------- */
MC('c30', 4, "A DC series motor is connected to its supply with no mechanical load at all. What is the danger?", ['It stalls and draws maximum current', 'The field current is tiny at light load, the flux is weak, and the speed can climb dangerously high (runaway)', 'It will run backwards', 'Nothing; a series motor runs at constant speed at all loads'], 1, "In a series motor the field current equals the armature current. At no load the current is small, so flux is small and the back-EMF needs a very high speed to balance the supply. Series motors must never be run unloaded.", _D);
MC('c30', 4, "Which DC motor type is best suited to a car starter or a traction drive (very high torque at standstill)?", ['Shunt-wound', 'Series-wound', 'Permanent-magnet with a fixed load', 'Separately excited with constant field'], 1, "In a series motor the same current builds the field and the torque: T ∝ I² (below saturation), so the torque at start-up is very large.", _D);
MC('c30', 4, "Which description of DC motor connections is correct?", ['Series motor: field winding in parallel with the armature; shunt motor: field in series', 'Series motor: field winding in series with the armature; shunt motor: field winding in parallel with the armature', 'Both use a permanent magnet field, differing only in the brush position', 'Compound motor: armature alone, with no field winding'], 1, "Series: one current path through field then armature. Shunt: field coil (many turns, thin wire) across the supply in parallel with the armature. Compound motors have both a series and a shunt field coil.", _D);
MC('c30', 5, "A shunt-wound motor is running at steady speed when its field winding circuit suddenly opens (a broken connection). What happens to the speed?", ['It stops immediately', 'It drops, because the field is lost', 'It rises sharply, because flux collapses toward residual and back-EMF drops, which raises the armature current and speed', 'It is unchanged, because the armature has a permanent field'], 2, "With the field gone (only residual flux), ε = kΦω drops, current jumps, and the machine speeds up until ε ≈ V again. The speed can reach destructive levels, so shunt motors need field-failure protection.", _D);
MS('c30', 5, "Select ALL correct statements about DC motor types.", ['A shunt-wound motor has nearly constant speed from light load to full load', 'A series motor has a torque that rises roughly as the square of the current (before saturation)', 'A permanent-magnet motor needs no field winding or field supply', 'A compound motor has only a series field winding'], [0, 1, 2], "A is right (the field is fixed so speed changes only slightly). B is right (Φ ∝ I, τ ∝ ΦI ∝ I²). C is right (the magnets provide the field). D is wrong: a compound motor has both series and shunt field windings.", _D);
MC('c30', 5, "A series-wound DC motor is connected to an AC supply of suitable voltage. What happens?", ['It cannot rotate at all', 'It can run, because reversing the current reverses both field and armature together, so the torque direction stays the same (a universal motor)', 'It runs but only in a direction set by the supply polarity', 'It turns at exactly the AC frequency'], 1, "Torque ∝ Φ × I_a. With both in series, both reverse together every half cycle, so the product keeps its sign. Power tools and vacuum cleaners use these universal motors (laminated fields to cut eddy loss).", _D);
NUM('c30', 5, "A series motor (magnetically unsaturated) produces 12 N·m at a starting current of 30 A. What torque, in N·m, does it produce at 10 A?", 1.33, 'N·m', "τ ∝ I² (flux ∝ I and torque ∝ ΦI). τ = 12 × (10/30)² = 12/9 = 1.33 N·m. A linear (shunt or PM) motor would give 4.0 N·m.", _D);
NUM('c30', 4, "A 24 V supply drives a motor through a PWM chopper at 35 % duty cycle. The motor’s armature resistance is 2.0 Ω and its back-EMF at this speed is 5.0 V. Assuming the inductance smooths the current, what average current, in A, flows?", 1.7, 'A', "Average applied voltage = 0.35 × 24 = 8.4 V. I_avg = (8.4 − 5.0)/2.0 = 1.7 A.", _D);
NUM('c30', 4, "A PWM signal at 20 kHz is high for 12.5 μs in every period and switches a 12 V supply. What is the average voltage, in V?", 3.0, 'V', "Period = 1/20 kHz = 50 μs. Duty = 12.5/50 = 25 %. V_avg = 0.25 × 12 = 3.0 V.", _D);
MC('c30', 5, "A transistor PWM-drives a motor. Why is a diode placed across the motor (cathode to the positive supply)?", ['To allow the motor to reverse', 'To give the inductive motor current a path when the transistor turns off and to clamp the voltage spike', 'To raise the average voltage above the supply', 'To charge the battery at low speed'], 1, "Current in the motor’s inductance cannot stop instantly. When the transistor opens, the flyback (freewheel) diode conducts the current and prevents a large voltage spike that would destroy the transistor.", _D);
NUM('c30', 4, "A motor turns at 6000 rpm with 0.020 N·m of torque. It drives a 15:1 gearbox that is 80 % efficient. What output torque, in N·m?", 0.24, 'N·m', "Ideal gearing multiplies torque by 15: 0.30 N·m. With 80 % efficiency, 0.30 × 0.80 = 0.24 N·m. Output speed is 6000/15 = 400 rpm.", _D);
NUM('c30', 5, "A 6-pole, 50 Hz induction motor has a synchronous speed of 1000 rpm. At full load its slip is 4.0 %. What is the rotor speed in rpm?", 960, 'rpm', "Slip s = (N_s − N)/N_s, so N = N_s(1 − s) = 1000 × 0.96 = 960 rpm.", _D);
NUM('c30', 5, "A 50 Hz supply drives an induction motor running at 4.0 % slip. What is the frequency of the currents induced in the rotor, in Hz?", 2.0, 'Hz', "The rotor sees the field sweeping by at only the slip speed, so f_rotor = s × f = 0.04 × 50 = 2.0 Hz.", _D);
MC('c30', 5, "Why can an induction motor never run exactly at synchronous speed?", ['The bearings always add friction', 'At synchronous speed there is no relative motion between rotor and rotating field, so no EMF or current is induced in the rotor and no torque is produced', 'The stator would overheat', 'The supply frequency would double'], 1, "Rotor currents are produced by relative motion (Faraday). With zero slip there is no induced EMF and so no torque; the rotor must lag (slip) to make torque.", _D);
NUM('c14', 5, "A separately excited DC generator with constant field produces 120 V at 1500 rpm. It is run at 1200 rpm with the same field, armature resistance 0.50 Ω, and delivers 20 A. What is the terminal voltage, in V?", 86, 'V', "EMF ∝ speed: 120 × 1200/1500 = 96 V. Terminal voltage = EMF − I R_a = 96 − 20 × 0.50 = 86 V.", _D);
MC('c30', 4, "The figure shows speed against torque for two DC motors, A and B. Which identification is most likely?", ['A is a series motor and B is a shunt motor', 'A is a shunt motor and B is a series motor', 'A and B are both series motors', 'A is a permanent-magnet motor and B is a series motor'], 0, "Curve A rises without limit as torque falls (runaway at light load), the signature of a series motor. Curve B droops only slightly from no load to heavy load: a shunt (or separately excited) motor.", _F('qf-c2-speedtorque'));

/* ---------- DEEP HISTORY (c17) ---------- */
MC('c17', 3, "Who, in 1785, used a torsion balance to show that the force between two small charged spheres varies as the inverse square of their separation?", ['Henry Cavendish', 'Charles-Augustin de Coulomb', 'Benjamin Franklin', 'Alessandro Volta'], 1, "Coulomb published the inverse-square law for electric (and magnetic pole) forces in 1785. Cavendish found similar results earlier but never published them.", _D);
MC('c17', 5, "Which statement about Henry Cavendish’s electrical work is true?", ['He published the inverse-square law for charges in 1785, before Coulomb', 'Much of his electrical work, including results that anticipated Ohm’s law, stayed unpublished until James Clerk Maxwell edited his papers in 1879', 'He invented the voltaic pile', 'He discovered electromagnetic induction'], 1, "Cavendish (d. 1810) left manuscripts that Maxwell edited and published as The Electrical Researches of the Honourable Henry Cavendish (1879). They showed he had anticipated Ohm’s law and the inverse-square law.", _D);
MC('c17', 4, "Galvani and Volta disagreed about the source of the twitching of a frog’s leg touched by two different metals. Which statement is correct?", ['Galvani argued for animal electricity in the tissue; Volta argued that contact of dissimilar metals was the source, which led to his pile in 1800', 'Volta argued for animal electricity; Galvani argued the metals were responsible', 'Both agreed it was caused by lightning', 'Galvani built the first battery to prove his view'], 0, "Galvani (1780s, published 1791) claimed a special animal electricity. Volta showed the metals and moist conductor alone could generate current and built the voltaic pile (1800).", _D);
MC('c17', 4, "Volta’s 1800 pile was made from:", ['copper and iron discs separated by dry paper', 'discs of two different metals, such as zinc and silver (or copper), separated by brine- or acid-soaked cloth or cardboard', 'a bar magnet spinning near a coil', 'Leyden jars connected in series'], 1, "Stacking zinc/silver discs with electrolyte-soaked spacers in series gave the first steady source of current, a huge advance over the brief discharges of Leyden jars.", _D);
MC('c17', 3, "In 1820, which scientist observed that a current in a wire deflects a nearby compass needle, linking electricity and magnetism for the first time?", ['Michael Faraday', 'Hans Christian Ørsted', 'André-Marie Ampère', 'Joseph Henry'], 1, "Ørsted (Oersted) announced the effect in July 1820. Ampère then worked out the mathematics within weeks.", _D);
MC('c17', 4, "Which of these is correctly credited to André-Marie Ampère?", ['Discovering that a current deflects a compass', 'Showing that parallel currents attract (and opposite currents repel) and proposing that magnetism arises from circulating currents', 'Inventing the lightning rod', 'Building the first electric generator with a commutator'], 1, "Ampère (1820 onward) founded electrodynamics: force between current-carrying wires, Ampère’s circuital law, and the idea of microscopic current loops in magnets. The compass observation was Ørsted’s; Pixii built the commutator generator.", _D);
MC('c17', 5, "Georg Ohm’s 1827 book, Die galvanische Kette, mathematisch bearbeitet, is best known for:", ['the first statement of the inverse-square law for charges', 'a mathematical theory of the galvanic circuit showing current proportional to the driving voltage and inversely related to resistance', 'the discovery of electromagnetic induction', 'the invention of the Leyden jar'], 1, "Ohm’s 1827 treatise formulated the relation we write I = V/R for circuits. The unit of resistance is named for him.", _D);
MC('c17', 5, "Which statement about Faraday’s iron-ring experiment of 1831 is correct?", ['A steady current in one winding induced a steady current in the other', 'The second winding showed a brief current only when the current in the first was switched on or off (changing flux)', 'It showed that the ring had to be permanently magnetised', 'It proved that electricity and magnetism were unrelated'], 1, "Faraday saw the galvanometer kick only when the primary current changed, leading him to the principle that a changing magnetic flux induces an EMF, the basis of transformers.", _D);
MC('c17', 4, "In 1821 Michael Faraday demonstrated:", ['electromagnetic induction using an iron ring', 'continuous electromagnetic rotation: a current-carrying wire circling a magnet, the first demonstration of the principle of the electric motor', 'the first transformer', 'the triode vacuum tube'], 1, "The 1821 rotation experiment (wire dipping in mercury around a magnet, and vice versa) came ten years before his discovery of induction (1831).", _D);
MC('c17', 4, "Joseph Henry is best known for which pair of achievements?", ['Discovery of self-inductance and building powerful insulated-wire electromagnets; first Secretary of the Smithsonian', 'Inventing the telephone and the phonograph', 'Discovering the Hall effect and the photoelectric effect', 'Formulating the laws of circuits and the bridge'], 0, "Henry’s insulated multilayer coils gave very strong electromagnets, he discovered self-inductance, and independently found induction around 1830–31. The SI unit of inductance is the henry.", _D);
MC('c17', 4, "William Sturgeon is credited with which of these?", ['The first electromagnet (1824–25): soft iron bent into a horseshoe, varnished and wound with bare copper wire', 'The voltaic pile', 'The telephone', 'The first transistor'], 0, "Sturgeon demonstrated his electromagnet in 1825 (first made 1824). Henry later improved it with insulated wire windings; Sturgeon also built an early commutator motor in 1832.", _D);
MC('c17', 5, "Hippolyte Pixii’s 1832 machine is significant because it was:", ['the first hand-cranked magneto-electric generator, to which a commutator was added (suggested by Ampère) to give pulsating DC', 'the first steam-powered alternator', 'the first vacuum-tube amplifier', 'the first transformer'], 0, "Pixii rotated a horseshoe magnet past coils; the output was alternating, and a commutator (on Ampère’s suggestion) rectified it into pulsating DC.", _D);
MC('c17', 4, "In 1838, which inventor demonstrated an electric-motor-driven boat carrying passengers on the Neva River in St Petersburg?", ['Thomas Davenport', 'Moritz (Boris) Jacobi', 'William Sturgeon', 'Werner von Siemens'], 1, "Jacobi’s motor boat (1838) carried about a dozen people. Davenport, an American blacksmith, patented the first US electric motor in 1837, a common distractor.", _D);
MC('c17', 4, "Who is credited with the first US patent for an electric motor (1837)?", ['Thomas Davenport', 'Joseph Henry', 'Nikola Tesla', 'Thomas Edison'], 0, "Vermont blacksmith Thomas Davenport received US patent No. 132 in 1837 for an electromagnetic motor.", _D);
MC('c17', 4, "James Joule’s 1840 law of heating states that the heat produced in a resistor is proportional to:", ['I R', 'I² R t', 'V/R', 'I/R²'], 1, "Joule found Q ∝ I²Rt. Heinrich Lenz reached the same result independently, so it is also called the Joule–Lenz law.", _D);
MC('c17', 4, "Lenz’s law (1834) is best stated as:", ['An induced current flows in the direction that opposes the change in flux that produced it', 'The induced EMF is proportional to the resistance of the loop', 'Induced current always flows clockwise', 'The magnetic flux through a closed surface is zero'], 0, "Lenz’s law follows from conservation of energy: if the induced current aided the change, it would create energy from nothing.", _D);
MC('c17', 4, "Gustav Kirchhoff formulated his circuit laws in 1845 while:", ['a 21-year-old student', 'director of Bell Laboratories', 'working for Thomas Edison', 'professor at Yale'], 0, "Kirchhoff was a student at Königsberg. KCL expresses conservation of charge; KVL expresses conservation of energy.", _D);
MC('c17', 5, "Which statement about James Clerk Maxwell is correct?", ['He predicted that changing E and B fields propagate as waves at the speed of light, and he died (1879) before Hertz’s experiments (1887–88) confirmed this', 'He detected radio waves himself in 1887', 'He invented the telephone', 'He discovered the electron'], 0, "Maxwell’s 1860s theory unified electricity, magnetism and light. Heinrich Hertz later produced and detected radio waves (1887–88), confirming it. Maxwell died in 1879.", _D);
MC('c17', 4, "Heinrich Hertz is remembered for:", ['first producing and detecting electromagnetic (radio) waves in the laboratory, 1887–88', 'discovering electromagnetic induction', 'inventing the first practical incandescent lamp', 'discovering the transistor effect'], 0, "Hertz used a spark-gap transmitter and loop receiver. The unit of frequency is named for him.", _D);
MC('c17', 4, "Which statement about Nikola Tesla is correct?", ['He developed the polyphase AC induction motor with a rotating magnetic field (patents of 1888)', 'He invented the voltaic pile', 'He discovered electromagnetic induction in 1831', 'He built the first telephone'], 0, "Tesla’s 1887–88 induction and synchronous motors used a rotating field from multiphase currents; Westinghouse licensed the patents. He had briefly worked for Edison in 1884. The unit of magnetic flux density is the tesla.", _D);
MC('c17', 4, "Thomas Edison’s Pearl Street Station, which opened in New York City in 1882, supplied:", ['direct current to customers for lighting', 'three-phase AC for motors', 'radio signals', 'high-voltage transmission at 100 kV'], 0, "Pearl Street was the first large central power station in the US, serving incandescent lamps with DC at about 110 V, which can only be sent a short distance economically.", _D);
MC('c17', 5, "The 'war of the currents' was won largely by AC because:", ['AC can be stepped up by transformers for low-loss long-distance transmission and stepped down for use', 'AC is inherently safer than DC', 'DC cannot power lamps', 'AC never produces heat in wires'], 0, "Transformers (Gaulard-Gibbs, Stanley, Westinghouse) work only with changing flux. High-voltage AC lines reduce I²R losses; DC of the 1880s could not be transformed easily. Niagara Falls (1895–96) confirmed AC for bulk power.", _D);
MC('c17', 4, "Werner von Siemens' 1866–67 dynamo was important because it introduced:", ['self-excitation: the machine’s own output fed its field electromagnets, removing the need for permanent magnets or a separate battery', 'the first use of alternating current for lighting', 'the first transformer', 'the first radio transmitter'], 0, "The dynamo-electric principle (also found by Wheatstone and Varley) gave much more powerful generators. The SI unit of conductance is named after Siemens.", _D);
MC('c17', 4, "On 14 February 1876, Alexander Graham Bell filed his telephone patent application. What else happened that day?", ['Elisha Gray filed a caveat for a similar device the same day', 'Edison filed for the incandescent lamp', 'Marconi sent the first transatlantic signal', 'Hertz detected radio waves'], 0, "Bell and Gray both filed at the US Patent Office on the same day; Bell’s patent was granted on 7 March 1876, and on 10 March he made the first intelligible call to Watson.", _D);
MC('c17', 4, "In December 1901 Guglielmo Marconi reported receiving a signal, the letter S in Morse, transmitted from Poldhu, Cornwall. He received it at:", ['Signal Hill, Newfoundland', 'Niagara Falls', 'New York City', 'Paris'], 0, "This was the first claimed transatlantic wireless transmission (12 December 1901). Marconi shared the 1909 Nobel Prize in Physics with Karl Ferdinand Braun.", _D);
MS('c17', 5, "Select ALL true statements about the invention of the transistor.", ['John Bardeen and Walter Brattain demonstrated a point-contact transistor at Bell Labs in December 1947', 'William Shockley later developed the junction transistor (1948)', 'Bardeen, Brattain and Shockley shared the 1956 Nobel Prize in Physics', 'The first transistor was a vacuum tube made by Lee de Forest in 1906'], [0, 1, 2], "The 1947 point-contact device (Bardeen and Brattain), Shockley’s 1948 junction transistor, and the 1956 Nobel prize are all correct. De Forest’s 1906–07 Audion was a vacuum-tube triode, not a transistor.", _D);
MC('c17', 5, "Jack Kilby (Texas Instruments, 1958) and Robert Noyce (Fairchild, 1959) each made an integrated circuit. Which pairing is correct?", ['Kilby: germanium device with wire interconnections (1958); Noyce: silicon planar device with deposited metal interconnections (1959)', 'Kilby: silicon planar chip (1959); Noyce: germanium chip with wires (1958)', 'Both built their chips from vacuum tubes', 'Kilby invented the transistor in 1947'], 0, "Kilby’s first IC was germanium with bonded wires. Noyce’s planar silicon approach (using Hoerni’s planar process) allowed the interconnections to be part of the chip. Kilby received the 2000 Nobel Prize in Physics.", _D);
MC('c17', 5, "Charles Proteus Steinmetz at General Electric is best known for:", ['the hysteresis law for magnetic losses and using complex numbers (phasors) to analyse AC circuits', 'inventing the telephone', 'inventing the voltaic pile', 'discovering the Hall effect'], 0, "Steinmetz’s 1890s work on hysteresis loss (∝ B^1.6) and symbolic (phasor) AC analysis made AC engineering practical.", _D);
MC('c17', 4, "Humphry Davy is credited with:", ['an early carbon arc lamp and electrolytic isolation of potassium and sodium (1807); Michael Faraday was his assistant', 'the first transistor', 'the discovery of induction', 'the telegraph'], 0, "Davy used a large voltaic battery to isolate potassium and sodium in 1807 and demonstrated bright electric arc lighting. He hired young Faraday as assistant in 1813.", _D);
MC('c17', 5, "The Wheatstone bridge was:", ['invented by Samuel Hunter Christie in 1833 and popularised by Charles Wheatstone from 1843', 'invented by Volta in 1800', 'invented by Kirchhoff in 1845', 'first described by Ohm in 1827'], 0, "Wheatstone did not invent the bridge: Christie described it in 1833, and Wheatstone publicised and used it for precise resistance measurement.", _D);
MC('c17', 5, "Which matching of circuit theorem and date is correct?", ['Thévenin (1883) and Norton (1926, Bell Labs)', 'Thévenin (1926) and Norton (1883)', 'Thévenin (1845) and Norton (1845)', 'Thévenin (1800) and Norton (1831)'], 0, "Léon Charles Thévenin published his theorem in 1883 (Helmholtz had found a version in 1853); Edward Lawry Norton of Bell Labs gave the current-source equivalent in 1926.", _D);
MC('c17', 4, "Edwin Hall discovered, in 1879 while a graduate student at Johns Hopkins, that:", ['a current-carrying conductor in a magnetic field develops a transverse voltage', 'a magnet moving through a coil induces a current', 'a compass is deflected by a wire', 'light ejects electrons from metal'], 0, "The Hall effect: charge carriers are deflected sideways by B, producing a transverse Hall voltage used in magnetic-field sensors.", _D);
NUM('c17', 5, "Hall voltage V_H = IB/(n e t). A copper strip (n = 8.5×10²⁸ m⁻³, e = 1.602×10⁻¹⁹ C) of thickness t = 0.10 mm carries 2.0 A in a 0.50 T field perpendicular to the strip. What is V_H, in μV?", 0.734, 'μV', "V_H = (2.0)(0.50)/((8.5×10²⁸)(1.602×10⁻¹⁹)(1.0×10⁻⁴)) = 1.0/1.362×10⁶ = 7.34×10⁻⁷ V = 0.734 μV. In metals the Hall voltage is tiny; semiconductors (small n) give much larger signals.", { dg: 1, tol: 0.03 });
MC('c17', 4, "Carl Friedrich Gauss and Wilhelm Weber:", ['built an electromagnetic telegraph at Göttingen in 1833; the CGS unit of magnetic flux density is the gauss and the SI unit of flux is the weber', 'invented the lightning rod in 1752', 'discovered radio waves in 1887', 'built the first integrated circuit'], 0, "Gauss and Weber’s 1833 Göttingen telegraph linked the observatory and physics institute. 1 T = 10⁴ gauss and 1 Wb = 1 V·s.", _D);
MC('c17', 4, "The Leyden jar, the first capacitor, was discovered:", ['independently by Ewald von Kleist (1745) and Pieter van Musschenbroek (1746)', 'by Volta in 1800', 'by Faraday in 1831', 'by Edison in 1879'], 0, "Kleist in Pomerania (1745) and Musschenbroek at Leiden (1746) found that a water-filled glass jar with a wire could store a strong charge.", _D);
MS('c17', 5, "Select ALL contributions credited to Benjamin Franklin.", ['Proposing that charge is conserved (one-fluid theory) and introducing the terms positive and negative', 'The 1752 kite experiment showing lightning is electrical', 'The lightning rod', 'The voltaic pile'], [0, 1, 2], "Franklin’s one-fluid theory, kite experiment (1752) and lightning rod are correct. Volta’s pile dates from 1800, after Franklin’s death (1790).", _D);
MC('c17', 4, "William Gilbert’s De Magnete (1600) is significant because it:", ['described the Earth as a giant magnet and introduced the term electricus (from Greek elektron, amber) for attraction by rubbing', 'reported the voltaic pile', 'announced the inverse-square law of charges', 'described the first transistor'], 0, "Gilbert tested his spherical lodestone 'terrella' and concluded Earth behaves as a magnet. He also distinguished electric attraction from magnetic attraction.", _D);
MC('c17', 5, "Stephen Gray’s 1729 experiments showed that:", ['electric charge can be conducted along a thread or wire over long distances, distinguishing conductors from insulators', 'charge comes in discrete units', 'currents create magnetic fields', 'light is an electromagnetic wave'], 0, "Gray transmitted charge through hemp thread and wire up to hundreds of feet, and discovered that some materials (silk) do not conduct.", _D);
MC('c17', 5, "Charles du Fay (1733) proposed that there are:", ['two kinds of electricity, vitreous and resinous, where like kinds repel and unlike attract', 'one kind of electricity only', 'three kinds of electricity corresponding to three primary colours', 'electricity that only flows in metals'], 0, "Du Fay’s two-fluid idea preceded Franklin’s one-fluid theory and positive/negative naming.", _D);
MC('c17', 5, "Put these in order from earliest to latest: (P) Volta’s pile, (Q) Coulomb’s torsion balance, (R) Faraday’s iron ring induction, (S) Ørsted’s compass experiment.", ['Q, P, S, R', 'P, Q, S, R', 'Q, P, R, S', 'P, Q, R, S'], 0, "Coulomb 1785, Volta 1800, Ørsted 1820, Faraday 1831.", _D);
MC('c17', 5, "Which list is in correct chronological order?", ['Pearl Street Station (1882), Hertz’s radio waves (1887), Tesla’s induction motor patents (1888), Marconi’s transatlantic signal (1901)', 'Hertz, Pearl Street, Marconi, Tesla', 'Tesla, Hertz, Pearl Street, Marconi', 'Marconi, Tesla, Hertz, Pearl Street'], 0, "1882 (Edison, New York), 1887–88 (Hertz), 1888 (Tesla patents), 1901 (Marconi). The others scramble these dates.", _D);
MC('c17', 5, "Which list is in correct chronological order (earliest first)?", ['Leyden jar, Franklin’s kite, Volta’s pile, Ørsted', 'Franklin’s kite, Leyden jar, Ørsted, Volta’s pile', 'Volta’s pile, Leyden jar, Franklin’s kite, Ørsted', 'Leyden jar, Volta’s pile, Franklin’s kite, Ørsted'], 0, "Leyden jar 1745–46, Franklin’s kite 1752, Volta’s pile 1800, Ørsted 1820.", _D);
MC('c17', 5, "Which list is in correct chronological order (earliest first)?", ['Fleming’s diode valve (1904), the transistor (1947), Kilby’s IC (1958), Noyce’s planar IC (1959)', 'Transistor, Fleming’s diode, Kilby, Noyce', 'Fleming’s diode, Noyce, Kilby, transistor', 'Kilby, Noyce, transistor, Fleming’s diode'], 0, "1904 (John Ambrose Fleming’s thermionic valve), 1947 (Bell Labs transistor), 1958 (Kilby, Texas Instruments), 1959 (Noyce, Fairchild).", _D);
MC('c17', 3, "Which of these units is NOT named after a person?", ['coulomb', 'hertz', 'lumen', 'ohm'], 2, "Lumen (luminous flux) comes from the Latin word for light. Coulomb, hertz and ohm honour Coulomb, Hertz and Ohm.", _D);
MC('c17', 3, "Ørsted’s name is also attached to a CGS unit. The oersted measures:", ['magnetic field strength H', 'electric charge', 'inductance', 'magnetic flux'], 0, "The CGS oersted measures magnetic field strength H (1 Oe = 1000/4π A/m). The gauss is B, the maxwell is flux.", _D);
NUM('c17', 3, "Earth’s magnetic field at the surface is about 0.5 gauss. What is this in microtesla? (1 T = 10⁴ gauss)", 50, 'μT', "0.5 G = 0.5×10⁻⁴ T = 50 μT.", _D);
MC('c17', 4, "Since the 2019 redefinition of SI units, the ampere is defined by:", ['fixing the elementary charge at exactly 1.602176634×10⁻¹⁹ coulomb', 'the current that makes 2×10⁻⁷ N per metre between wires 1 m apart', 'the current that deposits 1.118 mg of silver per second', 'the current produced by 1 V across 1 Ω of a reference resistor'], 0, "The 2019 definition fixes e exactly. The 1948 definition used the 2×10⁻⁷ N/m force between long parallel wires; the silver voltameter is an old international ampere.", _D);

/* ---------- units & dimensions (c03 and friends) ---------- */
MC('c03', 5, "The weber, the SI unit of magnetic flux, expressed in SI base units is:", ['kg·m²·s⁻²·A⁻¹', 'kg·m²·s⁻³·A⁻¹', 'kg·s⁻²·A⁻¹', 'kg·m²·s⁻²·A⁻²'], 0, "Wb = V·s and V = kg·m²·s⁻³·A⁻¹, so Wb = kg·m²·s⁻²·A⁻¹. The other options are the volt, the tesla and the henry.", _D);
MC('c03', 5, "The henry, the SI unit of inductance, expressed in SI base units is:", ['kg·m²·s⁻²·A⁻²', 'kg·m²·s⁻²·A⁻¹', 'kg·m²·s⁻³·A⁻²', 'kg⁻¹·m⁻²·s⁴·A²'], 0, "H = Wb/A = kg·m²·s⁻²·A⁻². The other options are the weber, the ohm and the farad.", _D);
MC('c03', 5, "The tesla, the SI unit of magnetic flux density, expressed in SI base units is:", ['kg·s⁻²·A⁻¹', 'kg·m²·s⁻²·A⁻¹', 'kg·m·s⁻²·A⁻¹', 'kg·s⁻¹·A⁻²'], 0, "T = Wb/m² = kg·m²·s⁻²·A⁻¹ / m² = kg·s⁻²·A⁻¹. Also T = N/(A·m).", _D);
MC('c03', 5, "The siemens, the SI unit of conductance, expressed in SI base units is:", ['kg⁻¹·m⁻²·s³·A²', 'kg⁻¹·m⁻²·s⁴·A²', 'kg·m²·s⁻³·A⁻²', 'kg⁻¹·m⁻²·s³·A'], 0, "S = 1/Ω = A/V. Ω = kg·m²·s⁻³·A⁻², so S = kg⁻¹·m⁻²·s³·A². The other options are the farad and the ohm.", _D);
MC('c03', 5, "The farad, the SI unit of capacitance, expressed in SI base units is:", ['kg⁻¹·m⁻²·s⁴·A²', 'kg⁻¹·m⁻²·s³·A²', 'kg·m²·s⁻²·A⁻²', 'kg⁻¹·m⁻²·s²·A'], 0, "F = C/V = (A·s)/(kg·m²·s⁻³·A⁻¹) = kg⁻¹·m⁻²·s⁴·A². The other options are the siemens and the henry.", _D);
MC('c03', 4, "What are the SI units of L/R (inductance divided by resistance)?", ['seconds', 'hertz', 'ohm-seconds', 'volts'], 0, "H/Ω = (V·s/A)/(V/A) = s. It is the RL time constant.", _D);
MC('c03', 5, "Which of these has units of seconds?", ['√(LC)', '1/√(LC)', 'C/L', 'L·C'], 0, "√(H·F) = √(V·s/A × A·s/V) = √(s²) = s. 1/√(LC) is an angular frequency (s⁻¹), C/L has units of Ω⁻², and LC has units of s².", _D);
MC('c03', 4, "The quantity B·ℓ·v (tesla × metre × metre per second) has the unit of:", ['volt', 'ampere', 'newton', 'joule'], 0, "T·m·(m/s) = (Wb/m²)·m²/s = Wb/s = V. This is the motional EMF.", _D);
MC('c03', 4, "The energy density in an electric field, ½ε₀E², has SI units of:", ['J/m³', 'J', 'W/m²', 'N·m'], 0, "ε₀E² has units (F/m)(V/m)² = (C/V/m)(V²/m²) = C·V/m³ = J/m³.", _D);
MC('c03', 4, "Which expression does NOT have the dimensions of power?", ['V²/R', 'I²R', 'I²/R', 'V·I'], 2, "V²/R, I²R and VI are all power. I²/R = A²/Ω is not.", _D);
MC('c03', 4, "One tesla equals:", ['1 N/(A·m)', '1 N·A/m', '1 N·m/A', '1 A·m/N'], 0, "F = BIL gives B = F/(IL), so T = N/(A·m).", _D);
NUM('c03', 3, "A 60 W lamp is left on for 5.0 hours. How much energy does it use, in megajoules?", 1.08, 'MJ', "E = P t = 60 W × 5.0 × 3600 s = 1.08×10⁶ J = 1.08 MJ (0.30 kWh).", _D);
NUM('c03', 3, "A 2000 μF capacitor is charged to 5.0 V. How much energy, in mJ, does it store?", 25, 'mJ', "E = ½CV² = 0.5 × 2.0×10⁻³ × 25 = 0.025 J = 25 mJ.", _D);
NUM('c03', 3, "A long straight wire carries 25 A. What is the field at 5.0 cm from it, in μT? (B = μ₀I/2πr)", 100, 'μT', "B = 2×10⁻⁷ × 25 / 0.050 = 1.0×10⁻⁴ T = 100 μT.", _D);

/* ---------- safety & wiring (c09, c10) ---------- */
MC('c09', 4, "Match the standard approximate thresholds for 60 Hz AC through the body: perception, let-go (can't release), and ventricular fibrillation risk.", ['about 1 mA, about 10 mA, about 100 mA', 'about 10 mA, about 100 mA, about 1 A', 'about 0.1 mA, about 1 mA, about 10 mA', 'about 10 mA, about 1 mA, about 100 mA'], 0, "Textbook values: ~1 mA perceptible tingle, ~10 mA muscles clamp and the victim cannot let go, ~100 mA (for a second or so) can cause ventricular fibrillation. It is current through the heart that is dangerous.", _D);
NUM('c09', 4, "Wet skin has a body resistance of about 1.0 kΩ. What current, in mA, flows from a hand touching 120 V to a grounded foot?", 120, 'mA', "I = V/R = 120/1000 = 0.12 A = 120 mA, above the ~100 mA fibrillation threshold. Dry skin (~100 kΩ) would give only about 1.2 mA.", _D);
MC('c09', 4, "A ground-fault circuit interrupter (GFCI) outlet trips when the difference between hot and neutral current exceeds about:", ['5 mA', '500 mA', '5 A', '15 A'], 0, "A Class A GFCI trips at 4–6 mA of leakage, well below the ~10 mA let-go and ~100 mA fibrillation levels.", _D);
MS('c10', 4, "Select ALL correct statements about North American 120 V household wiring.", ['The hot conductor is black (or red); the neutral conductor is white', 'The grounding conductor is bare or green and carries current only during a fault', 'The neutral and ground are bonded together only at the main service panel', 'The neutral conductor is fused so the circuit opens if the load shorts'], [0, 1, 2], "A, B and C are standard practice. Breakers and fuses go in the hot conductor only; fusing the neutral could leave the load live with the circuit open.", _D);
MC('c10', 4, "In US split-phase 120/240 V service, what is the voltage between the two hot legs, and what is the phase relation?", ['240 V; the two legs are 180° apart', '120 V; the two legs are in phase', '208 V; the two legs are 120° apart', '170 V; the two legs are 90° apart'], 0, "Each hot leg is 120 V to neutral, but the legs are 180° apart, so hot-to-hot is 240 V (used by dryers and ranges). 208 V is for three-phase wye service.", _D);
MC('c10', 4, "Why is a household switch or fuse placed in the hot conductor rather than the neutral?", ['So that when it is open, the lamp or appliance is at neutral potential (not live) and safe to touch', 'Because neutral carries no current', 'Because hot conductors are thicker', 'To reduce line voltage'], 0, "With the switch in the hot line, the load side is disconnected from the live supply when opened. In the neutral, the load would remain connected to hot with the circuit looking off.", _D);
NUM('c10', 3, "A 15 A, 120 V branch circuit has a 1100 W toaster and a 1500 W kettle both running at the same time. What total current, in A, do they draw?", 21.7, 'A', "P = 2600 W. I = P/V = 2600/120 = 21.7 A, which exceeds 15 A, so the breaker trips.", _D);

/* ---------- component ID / markings (c04, c16, c22) ---------- */
MC('c04', 4, "A ceramic disc capacitor is marked 104. Its value is:", ['100 nF', '10 nF', '10 pF', '100 μF'], 0, "Code: first two digits × 10^(third digit) pF = 10 × 10⁴ = 100,000 pF = 100 nF = 0.1 μF.", _D);
MC('c04', 4, "A surface-mount resistor is marked 472. Its resistance is:", ['4.7 kΩ', '472 Ω', '47.2 kΩ', '4.72 MΩ'], 0, "First two digits 47, multiplier 10² → 4700 Ω = 4.7 kΩ.", _D);
NUM('c04', 3, "A resistor is marked yellow, violet, orange, gold. What is its nominal value in kΩ?", 47, 'kΩ', "Yellow 4, violet 7, orange ×10³ → 47 kΩ, gold = ±5 %.", _D);
MC('c04', 4, "A five-band resistor reads brown, black, black, red, brown. Its value and tolerance are:", ['10.0 kΩ ± 1 %', '1.00 kΩ ± 2 %', '100 Ω ± 1 %', '10 kΩ ± 5 %'], 0, "Digits 1, 0, 0 → 100; multiplier red = ×10² → 10,000 Ω; tolerance brown = ±1 %.", _D);
MC('c22', 4, "An aluminium electrolytic capacitor has a stripe down one side. What does the stripe mark?", ['the negative lead', 'the positive lead', 'the rated temperature', 'the capacitance tolerance'], 0, "The stripe (often with a minus sign) marks the negative lead; the positive lead is usually longer. Reverse polarity can make the capacitor vent or burst.", _D);
MC('c22', 4, "You look at an unmarked 5 mm LED. The lens has a flat edge and one lead is longer. Which identification is correct?", ['Flat edge and shorter lead are the cathode; the longer lead is the anode', 'Flat edge and shorter lead are the anode', 'Flat edge and longer lead are both the cathode', 'Polarity cannot be told by looking'], 0, "Longer lead = anode (+); flat side of the lens rim and shorter lead = cathode (−).", _D);
MC('c22', 3, "On a rectifier diode such as a 1N4001, the printed band marks the:", ['cathode', 'anode', 'breakdown voltage', 'current rating'], 0, "Current flows easily from anode to cathode; the band marks the cathode end, like the bar in the diode symbol.", _D);
MC('c16', 4, "A three-terminal part marked 7805 in a TO-220 package is:", ['a fixed +5 V linear voltage regulator', 'a 7805 Ω resistor', 'an op amp', 'a −5 V regulator'], 0, "The 78xx series are positive fixed regulators (7805 = +5 V, 7812 = +12 V). The 79xx series are negative.", _D);
MS('c22', 4, "Select ALL components that must be installed with the correct polarity (they can be damaged or fail if reversed).", ['Electrolytic capacitor', 'LED', 'Rectifier diode', 'Metal-film resistor'], [0, 1, 2], "Electrolytic capacitors, LEDs and diodes are polarised. A resistor has no polarity.", _D);

/* rotate MC choices deterministically so the correct answer is not always the same letter */
(function () {
  DATA.questions.slice(_E2_N0).forEach((q, i) => {
    if (q.type !== 'mc') return;
    const k = (i * 7 + 1) % 4, n = q.ch.length; if (!k || n !== 4) return;
    q.ch = q.ch.map((_, j) => q.ch[(j + k) % n]);   /* new j holds old j+k */
    q.ans = (q.ans - k + n) % n;
  });
})();
